.hero-grid {
  display: grid;
  grid-template-columns: 1.05fr .95fr;
  gap: 2rem;
  align-items: center;
}
.eyebrow {
  display: inline-flex;
  background: oklch(93% 0.06 266 / .6);
  color: var(--primary-dark);
  border-radius: 999px;
  font-weight: 700;
  font-size: .8rem;
  padding: .35rem .75rem;
}
h1, h2, h3 { line-height: 1.15; letter-spacing: -.03em; margin: .2rem 0 .8rem; }
h1 { font-size: clamp(2rem, 4vw, 3.6rem); }
