}
.hero-panel { padding: 1rem; }
.tabs, .pill-tabs {
  display: inline-flex;
  border: 1px solid var(--border);
  background: var(--surface-2);
  border-radius: 999px;
  padding: .25rem;
  gap: .25rem;
}
.tab-btn {
  border: 0;
  background: transparent;
  color: var(--text-soft);
  font-weight: 700;
  border-radius: 999px;
  padding: .55rem 1rem;
