}
.tab-btn.active { background: #fff; color: var(--primary-dark); box-shadow: var(--shadow); }
.stat-bar {
  margin-top: 1.8rem;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1rem;
}
.stat-item { padding: 1.1rem; text-align: center; }
.stat-item strong { font-size: 1.6rem; display: block; }
.section { padding: 4rem 0; }
.grid-2, .grid-3, .grid-4 {
  display: grid;
  gap: 1rem;
}
.grid-2 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.grid-3 { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.grid-4 { grid-template-columns: repeat(4, minmax(0, 1fr)); }
.feature-card, .pricing-card, .quote, .faq-item, .step-card, .logo-item { padding: 1.2rem; }
.feature-card p, .pricing-card p, .quote p { color: var(--text-soft); }
.badge {
  display: inline-block;
  border-radius: 999px;
  font-size: .75rem;
  font-weight: 700;
  padding: .28rem .6rem;
  background: oklch(95% 0.07 145 / .45);
  color: oklch(40% 0.12 145);
}
.pricing-card.highlight { border: 2px solid oklch(65% 0.2 266 / .5); transform: scale(1.02); }
.logo-grid { display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: .8rem; }
.logo-item { text-align: center; font-weight: 700; color: var(--text-soft); }
.carousel { position: relative; overflow: hidden; }
.carousel-track {
  display: flex;
  transition: transform .4s ease;
}
.slide { min-width: 100%; }
.carousel-controls { margin-top: .8rem; display: flex; gap: .5rem; }
